import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  mlops: [
    L('From notebook to product',
      info('The model is the small part', 'A model in a notebook helps nobody. To be useful it must be **served**, **monitored**, **updated** and **reproducible**.\n\n**MLOps** is the practice of making that reliable and repeatable, in the same way DevOps did for software.'),
      order('Order the ML lifecycle', ['Collect and prepare data', 'Train and evaluate', 'Package the model', 'Deploy it', 'Monitor it', 'Retrain when needed'], 'A loop, not a line.'),
      mc('A colleague cannot reproduce your result from last month. What was most likely missing?', ['Versioned code, data and configuration', 'A bigger GPU', 'More epochs', 'A nicer notebook theme'], 'All three must be recorded.'),
      match('Match the tool type to its job', [['Git', 'Version the code'], ['DVC or a data catalogue', 'Version the data'], ['MLflow or Weights and Biases', 'Track experiments'], ['Docker', 'Fix the environment']]),
      mc('What does a model registry store?', ['Model versions, their metrics and which one is live', 'Raw training data', 'User passwords', 'GPU drivers'], 'It is the source of truth for deployments.'),
      tf('Fixing random seeds helps make training runs reproducible.', true, 'Along with pinned library versions.'),
      mc('Why turn a notebook into scripts or a pipeline?', ['So training can run automatically, be tested and be repeated', 'Notebooks cannot import numpy', 'Scripts are prettier', 'It lowers accuracy'], 'Hidden notebook state makes results fragile.'),
      mc('Which belongs in version control?', ['Training code and configuration', 'A 40 GB dataset as a plain file', 'Secret API keys', 'Temporary cache files'], 'Large data and secrets are handled by dedicated tools.')),

    L('Serving a model',
      info('Three ways to deliver predictions', '**Batch:** compute predictions on a schedule and store them. Cheap and simple.\n\n**Online:** an API answers each request in milliseconds.\n\n**Edge:** the model runs on the device itself: phone, camera, car.'),
      mc('Nightly churn scores for all customers, used by a marketing team next morning. Which pattern?', ['Batch', 'Online', 'Edge', 'Streaming'], 'Nobody is waiting for a single answer.'),
      mc('Approve or block a card payment while the customer waits. Which pattern?', ['Online', 'Batch', 'Weekly report', 'Manual review only'], 'The answer is needed in milliseconds.'),
      mc('Detect pedestrians in a moving car with no reliable network. Which pattern?', ['Edge', 'Batch', 'Online in a distant cloud', 'Email'], 'Latency and connectivity force on-device inference.'),
      order('A minimal online service', ['Load the model once at start-up', 'Receive a request and validate the input', 'Preprocess exactly as in training', 'Run the model', 'Return the prediction and log it'], 'Preprocessing must match training.'),
      info('Latency percentiles', 'Averages hide pain. If 99 requests take 20 ms and one takes 3 s, the mean looks fine and one user is furious.\n\nWe track **p50** (median), **p95** and **p99**: the time below which 95% or 99% of requests finish.'),
      mc('p99 latency = 800 ms means…', ['99% of requests finish within 800 ms', 'The average is 800 ms', '99 requests took 800 ms', 'The fastest request took 800 ms'], 'One in a hundred is slower.'),
      tf('A feature computed differently in training and in serving causes training-serving skew.', true, 'Share the code or use a feature store.')),

    L('Releasing and monitoring',
      info('Do not flip a switch', 'Safer ways to release a new model:\n\n- **Shadow:** it runs alongside the old one; its answers are logged, not used.\n- **Canary:** a small share of traffic goes to it.\n- **A/B test:** compare business impact.\n\nAlways keep a quick **rollback**.'),
      match('Match the release strategy', [['Shadow', 'New model predicts silently; users see the old one'], ['Canary', 'A small share of real traffic first'], ['A/B test', 'Measure the business effect of each version'], ['Rollback', 'Return quickly to the previous version']]),
      mc('Which strategy carries no risk to users?', ['Shadow deployment', 'Replacing everything at once', 'Canary at 50%', 'No testing'], 'Its predictions are not acted on.'),
      info('Drift', 'The world moves on after training.\n\n**Data drift:** the inputs change (new customer types, a new camera).\n\n**Concept drift:** the relationship changes (the same behaviour no longer means fraud).\n\nBoth degrade the model silently.'),
      mc('A new phone model sends images with different colours and your classifier degrades. This is…', ['Data drift', 'Concept drift', 'Overfitting', 'A release bug'], 'The input distribution changed.'),
      mc('Fraudsters change tactics, so old patterns no longer indicate fraud. This is…', ['Concept drift', 'Data drift only', 'Underfitting', 'A latency problem'], 'The meaning of the inputs changed.'),
      match('Match what to monitor', [['Service', 'Latency, errors, throughput'], ['Data', 'Schema, missing values, distribution shift'], ['Predictions', 'Score distribution'], ['Outcome', 'Real accuracy once labels arrive']]),
      type('PSI is a drift score. A common rule: above which value is the shift considered significant?', ['0.25', '.25'], 'Below 0.1 is stable; 0.1 to 0.25 deserves a look.')),

    L('Pipelines, CI/CD and interview level',
      info('Automate the path to production', '**CI/CD** for ML: every change is tested, built and deployed by a pipeline.\n\nBeyond code tests it adds **data validation**, **model evaluation gates** (do not ship if worse than the current model) and automated **retraining**.'),
      order('A CI/CD pipeline for a model', ['Run unit tests and data checks', 'Train and evaluate the candidate', 'Compare it with the current production model', 'Build and publish the container', 'Deploy as shadow or canary'], 'A gate before every promotion.'),
      mc('When should a model be retrained?', ['On a schedule, or when monitoring shows drift or a drop in quality', 'Never', 'Every minute regardless', 'Only when a user complains'], 'Use triggers you can measure.'),
      mc('Labels arrive three months late (loan defaults). How do you monitor meanwhile?', ['Watch input drift, the prediction distribution and proxy metrics', 'Wait three months', 'Assume all is well', 'Turn the model off'], 'Leading indicators cover the gap.'),
      mc('What is a feature store for?', ['Serving the same feature definitions offline and online, and sharing them across teams', 'Storing model weights', 'Scheduling GPUs', 'Hosting dashboards'], 'It removes a major source of skew.'),
      order('Order a strong answer to "How do you take a model to production?"', ['Make training reproducible and tested', 'Package and serve it to meet the latency need', 'Release gradually with a rollback', 'Monitor service, data and quality', 'Define when and how to retrain'], 'End with ownership.'),
      mc('Your model’s offline score is great and live performance is poor. First suspects?', ['Training-serving skew and leakage', 'The GPU', 'Too little logging', 'The colour scheme'], 'Compare the features the model sees online with those in training.'),
      mc('A good alert is one that…', ['Has a threshold, an owner and a runbook', 'Fires constantly', 'Nobody receives', 'Has no definition'], 'Otherwise it is noise.'),
      tf('Every production model should have a named owner and a documented rollback procedure.', true, 'Operations are part of the deliverable.')),

    L('Deeper: lineage and point-in-time data',
      info('Lineage', '**Data lineage** records where every dataset came from and which steps changed it. A good setup lets you start from any live model and trace back to its **code commit**, **data snapshot**, **configuration** and **environment**.\n\nWhen a bug is found in a cleaning step, lineage tells you exactly which models are affected.'),
      mc('What is data lineage?', ['A record of where data came from and how it was transformed', 'The number of columns in a table', 'A type of GPU', 'A chart colour scheme'], 'It connects every model to the data and code that produced it.'),
      mc('A bug is found in a data cleaning step. What tells you which models were trained on bad data?', ['Lineage linking each model to its data snapshot and pipeline version', 'Nothing: you must retrain everything', 'Asking each team member to remember', 'The model’s file size'], 'Recorded links turn a guess into a query.'),
      info('Point-in-time correctness', 'When you build a training set, each feature must have the value that was **known at prediction time**, not today’s value.\n\nJoin "customer lifetime spend" as of today onto a purchase from last March and you have leaked the future into the past. Feature stores and careful joins prevent this.'),
      mc('You train a churn model on events from January. Which feature join is correct?', ['Feature values as they were on each event’s date', 'The latest values from today', 'The average over all time', 'Random values'], 'Training must imitate what was knowable at the time.'),
      tf('Randomly shuffling time-ordered data before splitting is safe for a forecasting problem.', false, 'It lets the model train on the future and test on the past; split by time.'),
      match('Match the component to its job', [['Experiment tracking', 'Record parameters, metrics and artefacts for each run'], ['Model registry', 'Version and stage approved models'], ['Feature store', 'Serve consistent features offline and online'], ['Orchestrator', 'Run pipeline steps in order on a schedule']]),
      mc('Training computes avg_spend_30d in SQL; serving computes it in Python with different handling of nulls. Result?', ['Training-serving skew that is hard to spot', 'Faster training', 'Guaranteed better accuracy', 'No effect at all'], 'Two implementations drift apart; define each feature once.'),
      order('Order the steps to reproduce a past model', ['Find the model in the registry', 'Read its recorded commit, data snapshot and configuration', 'Check out that code and fetch that data version', 'Rebuild the environment from the pinned container', 'Re-run training and compare the metrics'], 'Everything needed is recorded, then replayed.')),

    L('Common mistakes and debugging',
      info('Silent failures', 'Machine-learning bugs rarely throw errors. The code runs, the numbers look plausible, and quality quietly falls.\n\nDebug in this order: **data** first, then **features**, then the **model**, then the **infrastructure**. Most real incidents are data problems.'),
      mc('What is wrong with this code?', ['The scaler saw the test rows before the split: leakage', 'Nothing is wrong', 'The scaler is the wrong class', 'There are too few rows'], 'Fit preprocessing on the training rows only.', 'scaler = StandardScaler().fit(X_all)\nX_scaled = scaler.transform(X_all)\nX_train, X_test = train_test_split(X_scaled)'),
      mc('Training used the column order [income, age]. What is the bug in this serving code?', ['The features are in a different order from training', 'A missing import', 'The wrong return type', 'Nothing is wrong'], 'The model silently reads age as income.', 'def predict(row):\n    x = [row["age"], row["income"]]\n    return model.predict([x])'),
      info('Alerts need owners', 'Checks that would have caught most incidents: **schema** (columns and types), **null rate**, **value ranges**, **row counts**, and a **score distribution** compared with training.\n\nEach alert needs a threshold, an owner and a runbook, or it becomes noise.'),
      mc('Live predictions are all nearly identical. First check?', ['Whether the input features arrive as expected, for example all defaults or nulls', 'The learning rate', 'The GPU fan', 'The tokeniser'], 'A broken upstream feed often fills features with defaults.'),
      fillc('df = df.sort_values("event_time")\ncut = int(len(df) * 0.8)\ntrain, test = df.iloc[:cut], df.iloc[___]', ['cut:', ':cut', 'cut', '0:0'], 'The test set is the most recent 20% of rows.'),
      match('Match the symptom to the likely cause', [['Great offline score, poor live score', 'Leakage or training-serving skew'], ['Accuracy decays slowly over months', 'Data or concept drift'], ['Latency spikes at night', 'Batch jobs competing for resources, or cold starts'], ['The model cannot be rebuilt', 'Unpinned libraries or unversioned data']]),
      mc('A fraud model shows AUC 0.99, which is suspiciously high. Which feature is the likeliest culprit?', ['"chargeback_filed", only known after fraud is confirmed', '"transaction_amount"', '"hour_of_day"', '"merchant_country"'], 'A feature that encodes the label’s outcome is leakage.'),
      order('Order the response when live accuracy suddenly drops', ['Confirm the drop with a trusted metric and time window', 'Check upstream data: schema, nulls and volumes', 'Compare feature distributions with training', 'Roll back to the previous model if users are harmed', 'Fix the cause and add a check that alerts next time'], 'Verify, localise, protect, fix, prevent.')),

    L('Case study: fraud scoring for card payments',
      info('The situation', 'A payment company processes **2,000,000 card transactions a day**. About **0.1%** are fraud. A score must be returned within a **50 ms** budget while the customer waits at the till. Fraud is confirmed only when a chargeback arrives, up to weeks later.\n\nYou make the decisions.'),
      mc('Which serving pattern fits?', ['Online: an API scores each transaction within the latency budget', 'Nightly batch scoring', 'Edge on the card', 'A monthly report'], 'The answer is needed while the customer waits.'),
      mc('Which evaluation approach fits a problem with 0.1% positives?', ['Precision and recall at a chosen threshold, weighted by the cost of misses and false alarms', 'Accuracy', 'The number of layers', 'Latency only'], 'A model that always says "legitimate" scores 99.9% accuracy and catches nothing.'),
      type('A model catches 80% of the fraud. How many fraudulent transactions per day does it catch?', ['1600', '1,600'], '0.1% of 2,000,000 is 2,000 frauds; 80% of 2,000 is 1,600.'),
      info('Delayed labels', 'A transaction is only labelled "fraud" once a chargeback arrives, so recent data is **unlabelled** and a naive training set treats unconfirmed fraud as legitimate.\n\nLet labels **mature** before training, and monitor with leading indicators (input drift, score distribution, flag rate) while you wait.'),
      mc('A candidate model improves recall offline. How should it be released?', ['Shadow on live traffic first, then a small canary with a rollback', 'Replace the current model at once', 'Skip testing', 'Run it only at weekends'], 'Prove it on real traffic before it affects customers.'),
      order('Order the release', ['Train the candidate on matured labels', 'Pass the evaluation gate against the current model', 'Run it in shadow on live traffic', 'Canary on 5% of traffic with alerts', 'Promote, and keep the old version ready for rollback'], 'Each stage reduces risk before the next.'),
      mc('Two weeks after launch the flag rate doubles but nobody complains. What first?', ['Check input drift and the score distribution; an upstream change is likely', 'Celebrate the extra catches', 'Ignore it', 'Turn monitoring off'], 'An unexplained jump is a signal to investigate, not to assume.'),
      mc('Fraudsters change tactics in response to the model. What helps most?', ['Frequent retraining on fresh labels, plus monitoring for concept drift', 'Never changing the model', 'Publishing how the model works', 'Maximising accuracy only'], 'An adversarial setting needs a fast feedback loop.')),

    L('Interview drill: MLOps',
      info('What interviewers listen for', 'MLOps questions test whether you have thought past the notebook. Strong candidates mention **reproducibility**, **safe release**, **monitoring** and **ownership** without prompting, and they say what each choice costs.'),
      mc('Interviewer: "What is MLOps?"', ['Practices for reliably building, deploying, monitoring and updating ML systems', 'A new neural network type', 'A GPU brand', 'A dashboard product'], 'It is DevOps thinking applied to data and models.'),
      mc('Follow-up: "How do you decide when to retrain?"', ['Triggers: a schedule plus monitored drift or quality drops, with a gate before promotion', 'Every hour, regardless', 'Never', 'When someone remembers'], 'Measurable triggers beat habit.'),
      info('Name the choice and its cost', 'Interviewers reward trade-offs: "Canary is slower than a full release but limits the damage"; "A feature store adds infrastructure but removes skew".\n\nA choice without its cost sounds like a slogan.'),
      mc('"Shadow or canary?"', ['Shadow tests with no user impact; a canary also shows the real effect on a small share of users', 'They are identical', 'Shadow is riskier', 'A canary uses no traffic'], 'Shadow is safe but silent; canary is real but exposed.'),
      mc('"What would you log for every prediction?"', ['Inputs or features, model version, prediction, timestamp and a request id', 'Only the output', 'Nothing, for privacy', 'Only the GPU temperature'], 'Without these you cannot debug, audit or build labels later.'),
      match('Match the interview question to the core of the answer', [['"How do you make it reproducible?"', 'Version code, data, configuration and environment'], ['"How do you avoid skew?"', 'Share feature code or use a feature store'], ['"How do you release safely?"', 'Shadow, canary, an evaluation gate and rollback'], ['"How do you know it is still good?"', 'Monitor service, data, predictions and outcomes']]),
      order('Order a strong answer to "Design the MLOps for a team shipping its first model"', ['Start with version control, tracking and a reproducible pipeline', 'Containerise and add automated tests and data checks', 'Add a registry and an evaluation gate', 'Deploy with a canary and a rollback', 'Monitor and set retraining triggers'], 'Foundations first, then release, then operations.'),
      tf('"Automate everything on day one" is a stronger answer than "start small and automate the painful steps first".', false, 'Pragmatic sequencing shows experience.'))
  ],

  'edge-deploy': [
    L('Why run on the device?',
      info('Edge inference', 'Sometimes the model must run where the data is: a camera, a phone, a car.\n\nReasons: **latency** (no round trip), **connectivity** (no network), **privacy** (data stays local), **cost** (no cloud bill per request).'),
      match('Match the reason to the example', [['Latency', 'Emergency braking cannot wait for a server'], ['Connectivity', 'A tractor in a field with no signal'], ['Privacy', 'In-cabin camera video stays in the car'], ['Cost', 'Millions of devices calling a cloud API']]),
      mc('What is the main difficulty of edge deployment?', ['Limited compute, memory and power', 'Too much compute', 'No need for testing', 'Models cannot run on CPUs'], 'The model must fit a small budget.'),
      mc('Which model family was designed for mobile and embedded use?', ['MobileNet', 'A 100-layer transformer', 'GPT-style LLMs', 'Random noise'], 'Depthwise separable convolutions make it light.'),
      info('Know your budget', 'Before choosing a model, write down the limits:\n\n- **Latency** per frame or request\n- **Memory:** RAM and flash\n- **Power** and heat\n- **Accuracy** floor\n\nThen measure on the **real device**, not your laptop.'),
      mc('A camera runs at 30 frames per second. How long may processing one frame take to keep up?', ['About 33 ms', 'About 300 ms', '3 s', '1 ms exactly'], '1000 ms / 30.'),
      type('A function must run at 20 Hz. What is the time budget per cycle, in milliseconds?', ['50'], '1000 / 20.'),
      tf('A model that is fast on a desktop GPU is guaranteed to be fast on an embedded chip.', false, 'Operator support and hardware differ. Always profile on the target.')),

    L('Shrinking a model',
      info('Four levers', '1. **Quantisation:** 8-bit integers instead of 32-bit floats.\n2. **Pruning:** remove weights or whole channels that matter little.\n3. **Distillation:** train a small "student" to copy a large "teacher".\n4. **Architecture:** efficient layers and a smaller input.'),
      match('Match the technique', [['Quantisation', 'Fewer bits per number'], ['Pruning', 'Remove unimportant weights or channels'], ['Distillation', 'A small model learns from a large one'], ['Smaller input resolution', 'Fewer pixels to process']]),
      type('A 40 MB float32 model is quantised to int8. Roughly how many MB?', ['10'], 'A quarter of the size.'),
      mc('Which kind of pruning gives real speed-ups on ordinary hardware?', ['Structured: removing whole channels or filters', 'Unstructured: zeroing scattered weights', 'Random pruning', 'None'], 'Scattered zeros need sparse support to help.'),
      mc('In distillation, what does the student learn from?', ['The teacher’s output probabilities (soft targets)', 'Random labels', 'Only the hard labels', 'The teacher’s file size'], 'Soft targets carry more information than a single label.'),
      info('Depthwise separable convolution', 'A standard 3×3 convolution mixes space and channels in one costly step. MobileNet splits it:\n\n- **depthwise:** one 3×3 filter per input channel\n- **pointwise:** a 1×1 convolution to mix channels\n\nRoughly 8 to 9 times fewer parameters for a 3×3 kernel.'),
      type('A standard 3×3 convolution from 32 to 64 channels has how many weights (ignore biases)?', ['18432'], '3 × 3 × 32 × 64.'),
      type('The depthwise-separable version: 3×3 depthwise on 32 channels plus 1×1 pointwise to 64. How many weights (ignore biases)?', ['2336'], '3·3·32 + 32·64 = 288 + 2048.')),

    L('Conversion and verification',
      info('Getting onto the target', 'Typical routes:\n\n- **ONNX → TensorRT** for NVIDIA devices\n- **TFLite / LiteRT** for phones and microcontrollers\n- **OpenVINO** for Intel\n- **Generated C** for small models on microcontrollers\n\nEach toolchain supports only certain operators.'),
      mc('Export fails with "unsupported operator". Usual fix?', ['Replace the layer with a supported equivalent, or change the model', 'Ignore it', 'Buy a new laptop', 'Raise the learning rate'], 'Design the model with the target in mind.'),
      order('Order a conversion workflow', ['Export the trained model', 'Convert it with the target toolchain', 'Run the same test inputs through both versions', 'Compare outputs within a tolerance', 'Measure accuracy on the full validation set'], 'Never trust a conversion you have not checked.'),
      mc('What is a back-to-back test?', ['Feeding identical inputs to the reference and the deployed model and comparing outputs', 'Running two devices in parallel in the field', 'Testing the model twice', 'A hardware burn-in'], 'It proves the conversion preserved behaviour.'),
      mc('Accuracy dropped after int8 conversion. First thing to check?', ['That the calibration data is representative', 'The cable', 'The screen', 'The file name'], 'Then look layer by layer.'),
      match('Match what to measure on the device', [['Latency', 'Time per inference, including the worst case'], ['RAM', 'Peak working memory'], ['Flash', 'Size of code and weights'], ['Power', 'Energy use and heat']]),
      mc('Why does preprocessing often dominate edge latency?', ['Resize and colour conversion run on a slow CPU', 'The model is always slow', 'Flash is slow to read', 'It never does'], 'Profile the whole pipeline, not only the network.'),
      tf('After conversion you should re-measure accuracy on the validation set.', true, 'Matching a few samples is not enough.')),

    L('Real-time systems and interview level',
      info('Worst case, not average', 'In a real-time system a late answer is a wrong answer. Engineers design for **worst-case execution time (WCET)**.\n\nThat means: no dynamic memory in the loop, bounded loops, fixed input sizes, and measuring on target under load.'),
      mc('Average inference is 12 ms, worst case 60 ms, deadline 33 ms. Verdict?', ['Not acceptable: the worst case misses the deadline', 'Fine, the average is low', 'Fine, 60 is rare', 'Cannot tell'], 'Find and remove the cause of the spikes.'),
      mc('A common cause of occasional latency spikes on embedded Linux?', ['Memory allocation, garbage collection or thermal throttling', 'The model learning', 'Too few layers', 'Good cache use'], 'Pre-allocate, pin threads, watch temperature.'),
      mc('The chip overheats and slows down after ten minutes. This is…', ['Thermal throttling', 'Overfitting', 'Data drift', 'Quantisation error'], 'Test for sustained performance, not a burst.'),
      order('Order a strong answer to "Make this model run in real time on an embedded device"', ['State the budget: latency, memory, accuracy', 'Profile to find where the time goes', 'Pick an efficient architecture and input size', 'Quantise, prune or distil', 'Convert, verify equivalence and measure on target'], 'Measure, then optimise the biggest item.'),
      mc('You must choose between a slightly more accurate model at 45 ms and a slightly weaker one at 25 ms, with a 33 ms budget. Choose…', ['The 25 ms model', 'The 45 ms model', 'Either', 'Neither'], 'A model that misses the deadline is not usable.'),
      mc('Which is true of deploying a random forest on a microcontroller?', ['It can be generated as nested if/else in C with no floating-point library', 'It needs a GPU', 'It cannot be done', 'It needs Python on the device'], 'Trees map naturally to branches and comparisons.'),
      mc('Interviewer: "What would you check before promising a frame rate?"', ['End-to-end timing on the target, including pre- and postprocessing, under realistic load', 'Only the model’s FLOPs', 'The laptop benchmark', 'The paper’s claims'], 'End to end and on the real hardware.'),
      tf('FLOPs alone predict latency accurately on every device.', false, 'Memory access patterns and operator support matter as much.')),

    L('Deeper: how quantisation works',
      info('Integers with a scale', 'Affine quantisation stores each value as an 8-bit integer **q** plus two numbers for the whole tensor: a **scale** and a **zero point**. The real value is recovered as:\n\n`real = scale × (q − zero_point)`\n\nSo int8 needs one byte per weight instead of four, and integer arithmetic is faster and cheaper in energy on most chips.'),
      mc('Which formula recovers an approximate real value from an int8 value q?', ['scale × (q − zero_point)', 'q squared', 'q + 1000', 'q divided by scale only'], 'The scale sets the step size and the zero point shifts the range.'),
      type('An int8 tensor has scale 0.1 and zero point 0. What real value does q = 25 represent?', ['2.5'], '0.1 × (25 − 0) = 2.5.'),
      type('A model has 5 million parameters stored as int8 (1 byte each). Roughly how many MB are the weights?', ['5', '5 MB'], '5 million bytes is about 5 MB.'),
      info('Calibration, PTQ and QAT', '**Post-training quantisation (PTQ)** picks scales by running a **calibration set** through the model. It is quick, and usually costs a little accuracy.\n\n**Quantisation-aware training (QAT)** simulates the rounding during training so the model learns to cope with it. Use it when PTQ loses too much.\n\nA **per-channel** scale (one per output channel) is usually more accurate than a single **per-tensor** scale.'),
      mc('PTQ lost 6 accuracy points even with good calibration data. Next option?', ['Quantisation-aware training', 'Add more layers', 'Raise the clock speed', 'Use float64'], 'QAT lets the weights adapt to rounding.'),
      match('Match the term', [['Per-tensor scale', 'One scale for the whole tensor, the simplest option'], ['Per-channel scale', 'One scale per output channel, usually more accurate'], ['PTQ', 'Quantise after training using calibration data'], ['QAT', 'Simulate quantisation during training']]),
      mc('Fusing convolution, batch norm and ReLU into one operator helps mainly because…', ['It cuts memory reads and writes between layers', 'It adds parameters', 'It always raises accuracy', 'It removes the need for a device'], 'Moving data costs more time and energy than the arithmetic.'),
      mc('A layer is memory-bound. Which change helps most?', ['Move less data, for example lower precision or smaller activations', 'Add more idle arithmetic units', 'Raise the learning rate', 'Rename the layer'], 'When data movement is the limit, more arithmetic does not help.')),

    L('Common mistakes and debugging',
      info('Bugs live in the seams', 'Most edge bugs are not in the network. They are in the **seams** around it: colour order (RGB or BGR), tensor layout (channels first or last), normalisation, resize method, and units.\n\nThe model runs happily on wrong input and returns plausible nonsense.'),
      mc('A converted model gives poor but plausible results. The camera library returns BGR images and the model was trained on RGB. Fix?', ['Convert the channel order before inference', 'Retrain with BGR labels', 'Raise the clock speed', 'Quantise more aggressively'], 'Match the preprocessing used in training exactly.'),
      mc('Training used RGB and normalised pixels as (x / 255 − 0.5) / 0.5. What is wrong here?', ['The channel order and the normalisation both differ from training', 'Nothing is wrong', 'The image is too large', 'The file type is wrong'], 'Input to the model must be identical in meaning to the training input.', 'img = cv2.imread(path)      # uint8, 0..255, BGR\nx = img / 255.0\nout = model(x[None])'),
      info('Find the first divergence', 'To debug a conversion, run the **same input** through the reference and the converted model and compare **every layer**. The first layer that differs beyond the tolerance is where to look: a quantisation range, an unsupported operator replaced by an approximation, or a different padding rule.'),
      mc('Outputs match the reference up to layer 14 and diverge at layer 15, an int8 softmax. Next step?', ['Inspect that layer’s quantisation range and consider keeping it in higher precision', 'Rebuild the whole model from scratch', 'Ignore it', 'Change the camera'], 'Local divergence calls for a local fix.'),
      fillc('x = img[:, :, ___]  # convert BGR to RGB', ['::-1', '0', ':1', '1:1'], 'Reversing the last axis swaps the channel order.'),
      match('Match the symptom to the likely cause', [['Fast at first, slow after minutes', 'Thermal throttling'], ['Occasional 60 ms spikes', 'Memory allocation or competing processes'], ['Works on the laptop, fails on the device', 'Unsupported operator or different library version'], ['Accuracy drops only on dark images after int8', 'Calibration data lacked dark images']]),
      mc('A benchmark shows 25 ms on the device, but the product measures 70 ms. Likely cause?', ['Preprocessing, buffer copies and other processes are not in the benchmark', 'The benchmark is always right', 'Flash is full', 'The colour order'], 'Measure the whole pipeline in the real product.'),
      order('Order a debugging session after conversion', ['Run identical inputs through the reference and the converted model', 'Compare outputs layer by layer to find the first divergence', 'Check preprocessing, layout and quantisation ranges at that point', 'Fix and rebuild the converted model', 'Re-measure accuracy and latency on the device'], 'Localise before you fix, and re-measure on the target.')),

    L('Case study: in-cabin driver monitoring',
      info('The situation', 'A driver-monitoring system watches an infrared camera at **30 frames per second** and must warn if the driver’s eyes stay closed for **1.5 seconds**. The limits: **33 ms** per frame in total, a small memory budget, and recall of at least **95%** for closed eyes.\n\nYou make the decisions.'),
      mc('Where should inference run?', ['On the device: low latency, no dependence on a network, and the video stays in the car', 'In a distant cloud', 'On the driver’s own phone only', 'Nowhere'], 'Latency, connectivity and privacy all point to the edge.'),
      mc('Candidate A: 96% recall at 40 ms. Candidate B: 94% recall at 20 ms. The floor is 95% within 33 ms. What now?', ['Neither passes: shrink A or improve B, then re-measure', 'Ship A', 'Ship B', 'Ship both'], 'A deadline miss and an accuracy miss are both failures.'),
      info('Quantise and measure again', 'The team quantises A to int8. On the device it now takes 22 ms with 95.5% recall, so it passes both limits.\n\nThe key habit: every change is followed by a **measurement on the target**, never an assumption.'),
      type('The alert fires after eyes are closed for 1.5 seconds. At 30 frames per second, how many consecutive frames is that?', ['45'], '30 × 1.5 = 45 frames.'),
      mc('Testing shows recall falls for drivers wearing sunglasses. What next?', ['Collect and add such data, evaluate per condition, then retrain', 'Ignore it, since it is rare', 'Remove the alert', 'Only raise the image resolution'], 'Slice the evaluation by condition and fix the weak slice.'),
      order('Order the validation', ['Back-to-back test of the converted model against the reference', 'Measure worst-case latency on the target under sustained load', 'Test in heat and in varied lighting', 'Evaluate recall for each condition', 'Sign off with a written statement of the limits'], 'Correctness, timing, environment, coverage, documentation.'),
      mc('After 20 minutes in a hot car, latency rises from 22 ms to 38 ms. Verdict?', ['Thermal throttling breaks the deadline; fix with cooling, a lighter model or a safe fallback', 'Fine, the average is low', 'Irrelevant to accuracy', 'Proof the model is more accurate'], 'Real-time systems must hold their deadline under sustained load.'),
      tf('Reporting only the average latency is enough for the sign-off.', false, 'Worst-case and sustained latency decide whether deadlines are met.')),

    L('Interview drill: edge deployment',
      info('What interviewers listen for', 'Edge interviews reward **numbers** and **measurement**. Strong candidates state a budget (latency, memory, accuracy), do quick arithmetic aloud, and say they would profile on the real device before promising anything.'),
      mc('Interviewer: "Why run on the edge rather than in the cloud?"', ['Latency, connectivity, privacy and cost per request', 'Edge devices are always faster than data centres', 'Cloud servers cannot run models', 'It needs no testing'], 'Name the reason that matters for the use case.'),
      mc('Follow-up: "What is quantisation, and what is the risk?"', ['Fewer bits per number to cut size and time; accuracy can drop, so calibrate and re-measure', 'Making the model larger', 'Removing the labels', 'Moving to float64'], 'Always mention the accuracy risk and how you check it.'),
      info('Show your arithmetic', 'Small calculations signal real experience:\n\n- 30 fps means about 33 ms per frame\n- float32 to int8 is about 4 times smaller\n- 1.5 s at 30 fps is 45 frames\n\nSay the numbers aloud, then say how you would verify them on the target.'),
      mc('"Quantisation, pruning or distillation first?"', ['Start with the cheap options, a lighter architecture and quantisation, then distil or prune if still too big', 'Always prune first', 'Always distil first', 'Do none of them'], 'Order by effort and risk.'),
      type('A 25 MB float32 model is quantised to int8. About how many MB is it afterwards?', ['6.25', '6', '6.3'], 'A quarter of the size: 25 ÷ 4 = 6.25.'),
      match('Match the interview question to the core of the answer', [['"How do you verify conversion?"', 'Back-to-back outputs within a tolerance, then the full validation set'], ['"Why is it slow only in the product?"', 'Preprocessing, copies and contention in the full pipeline'], ['"How do you guarantee real time?"', 'Measure worst case on target and avoid allocations'], ['"The model does not fit in flash."', 'Quantise, prune or choose a smaller architecture']]),
      order('Order a strong answer to "You have a 90 MB float32 model and a 12 MB flash budget"', ['Restate the limit: the weights must fit in 12 MB with room for code', 'Quantise to int8, giving about 22.5 MB', 'Choose a lighter architecture, or prune or distil, to get below 12 MB', 'Re-evaluate accuracy and latency on the device', 'Say what you would trade off if accuracy falls short'], 'Quantisation alone is not enough here: 90 ÷ 4 is still 22.5 MB.'),
      tf('Saying "I would measure on the real device first" is a strong signal in an edge interview.', true, 'It shows you know that laptop results do not transfer.'))
  ],

  'ml-system-design': [
    L('Start with the problem',
      info('The interview that scares people', 'A system-design question is open on purpose: "Design a recommendation system."\n\nThe mistake is naming a model in the first minute. Strong candidates spend the first five minutes on **questions**: goal, users, scale, constraints.'),
      order('Order the first minutes of a design interview', ['Clarify the business goal', 'Ask who the users are and how predictions are used', 'Ask about scale and latency', 'Agree on a success metric', 'Only then propose a design'], 'Requirements first.'),
      mc('"Design a fraud detection system." Best first response?', ['"What does a missed fraud cost compared with a false alarm, and how fast must we decide?"', '"I would use XGBoost."', '"A transformer with attention."', '"Kubernetes."'], 'The costs and the latency shape everything else.'),
      match('Match the question to what it decides', [['How many requests per second?', 'Serving architecture'], ['How fast must we answer?', 'Model size and caching'], ['What does an error cost?', 'Metric and threshold'], ['How often does the world change?', 'Retraining schedule']]),
      mc('Which is a business metric, not a model metric?', ['Revenue per user', 'AUC', 'Log-loss', 'F1'], 'Tie your offline metric to it.'),
      info('Baseline first', 'Always propose a **simple baseline** before the clever design: most popular items, a few rules, logistic regression.\n\nIt ships fast, sets the bar and tells you whether complexity is worth it.'),
      mc('A sensible baseline for product recommendations?', ['Most popular items in the user’s category', 'A custom large language model', 'Random items', 'No recommendations'], 'Surprisingly hard to beat by much.'),
      tf('It is acceptable to say that a problem may not need machine learning.', true, 'It shows judgement.')),

    L('Data and features',
      info('Where do labels come from?', 'No labels, no supervised model. Sources:\n\n- **Explicit:** people label examples.\n- **Implicit:** clicks, purchases, corrections.\n- **Delayed:** fraud confirmed weeks later.\n\nAsk about bias: you only observe outcomes for what you showed or approved.'),
      mc('Click data as labels for a recommender has which bias?', ['Users can only click what was shown to them', 'Clicks are always wrong', 'There are too few clicks', 'Clicks are explicit ratings'], 'Position and selection bias. A feedback loop.'),
      mc('You only know whether a loan defaulted if it was approved. This is…', ['Selection bias', 'Data drift', 'Overfitting', 'Label noise only'], 'Rejected applicants have no outcome.'),
      match('Match the feature type', [['User features', 'Age of account, past purchases'], ['Item features', 'Category, price'], ['Context features', 'Time of day, device'], ['Interaction features', 'How often this user viewed this category']]),
      mc('A feature needs the last 5 minutes of user activity. It must be computed…', ['In near real time (streaming)', 'In a nightly batch', 'Once a year', 'Never'], 'Freshness requirements decide batch versus streaming.'),
      mc('Why split by time when evaluating a recommender?', ['To imitate predicting the future from the past', 'It is faster', 'Random splits are illegal', 'To get higher scores'], 'Random splits leak future behaviour.'),
      tf('Features must be computed the same way for training and for live prediction.', true, 'Otherwise: training-serving skew.'),
      mc('Personal data is involved. What must the design address?', ['Consent, minimisation, access control and retention', 'Nothing', 'Only accuracy', 'Only latency'], 'Raise privacy without being asked.')),

    L('Architecture patterns',
      info('Retrieve, then rank', 'You cannot score 10 million items per request with a heavy model. Use two stages:\n\n1. **Candidate retrieval:** a cheap method picks a few hundred items (embeddings and nearest-neighbour search).\n2. **Ranking:** a richer model orders them precisely.'),
      order('Order a recommendation request', ['Receive the user and context', 'Retrieve a few hundred candidates', 'Fetch features for user and candidates', 'Rank candidates with the model', 'Apply business rules and return the top results'], 'Funnel from cheap to precise.'),
      mc('Why two stages instead of one model?', ['To meet latency: a cheap filter first, an expensive model on few items', 'Two models are always more accurate', 'It uses less data', 'Fashion'], 'A cost and latency trade-off.'),
      match('Match the pattern to the problem', [['Two-stage retrieval and ranking', 'Recommendations and search'], ['RAG', 'Questions over documents'], ['Cascade', 'A cheap model for easy cases, an expensive one for hard cases'], ['Human in the loop', 'High-risk decisions']]),
      mc('Which lowers latency for repeated requests?', ['Caching results or features', 'A larger model', 'More logging', 'A longer timeout'], 'Do not recompute what you already know.'),
      mc('A new user has no history. This is the…', ['Cold-start problem', 'Vanishing gradient', 'Drift problem', 'Skew problem'], 'Fall back to popularity and content features.'),
      mc('Batch or online prediction for a homepage feed that should react to the last click?', ['Online, or precomputed candidates with online re-ranking', 'Monthly batch', 'Yearly batch', 'No prediction'], 'A hybrid is common.'),
      tf('Business rules, such as "never show out-of-stock items", are usually applied after the model.', true, 'As filters and re-ranking.')),

    L('Evaluate, operate and interview level',
      info('Offline, then online', '**Offline:** metrics on held-out data (NDCG, recall@k, AUC). Cheap, fast, approximate.\n\n**Online:** an A/B test on the business metric. Slow, real.\n\nA design answer should mention both, plus **guardrails** such as latency and complaints.'),
      mc('Offline NDCG improved and the A/B test is flat. Likely reason?', ['The offline metric does not track what users value, or logged data is biased', 'A/B tests are broken', 'NDCG is wrong by definition', 'Too many users'], 'Check the link between proxy and goal.'),
      type('NDCG is 1.0 when the results are in what order? One word.', ['ideal', 'perfect', 'best', 'optimal'], 'Most relevant first.'),
      mc('A feedback loop in a recommender means…', ['The model’s own choices shape the data it is later trained on', 'Audio distortion', 'Slow training', 'A circular import'], 'Add exploration so new items get a chance.'),
      order('Order a complete design answer', ['Clarify requirements and metric', 'Data, labels and features', 'Baseline, then the model and architecture', 'Serving: latency, scale, caching', 'Evaluation offline and online', 'Monitoring, retraining and risks'], 'Use it as your checklist in every design interview.'),
      match('Match the trade-off', [['Accuracy', 'against latency and cost'], ['Freshness', 'against pipeline complexity'], ['Precision', 'against recall'], ['Build', 'against buy']]),
      mc('How should you finish a design answer?', ['Summarise, name the biggest risk, say what you would build first', 'Stop talking', 'Add five more models', 'Apologise'], 'Shows prioritisation.'),
      mc('"Design a system to answer employee questions from internal documents." Core pattern?', ['RAG with permission-aware retrieval', 'Fine-tune a model on all documents monthly', 'A decision tree', 'A recommender'], 'Fresh, citable, access-controlled.'),
      tf('Stating your assumptions aloud is a good habit in a design interview.', true, 'It lets the interviewer correct you early.')),

    L('Deeper: back-of-envelope estimates',
      info('Do the arithmetic aloud', 'Interviewers love quick estimates. Remember that a day has **86,400 seconds**, close to 100,000, so dividing daily requests by about 100,000 gives requests per second.\n\nThen allow for **peaks** (often 3 to 5 times the average) and for **headroom** so servers are not run at full load.'),
      type('A service receives 8,640,000 requests per day. What is the average number of requests per second?', ['100'], '8,640,000 ÷ 86,400 = 100.'),
      type('Peak traffic is 3 times the average of 100 requests per second. What peak capacity is needed, in requests per second?', ['300'], '3 × 100 = 300.'),
      info('Embeddings and nearest-neighbour search', 'Candidate retrieval stores an **embedding** (a vector) for every item. Storage is **items × dimensions × bytes per number**, for example 4 bytes for float32.\n\nChecking a query against every vector is too slow at millions of items, so systems use **approximate nearest-neighbour (ANN)** indexes that give up a little recall for a large speed-up.'),
      type('How much storage do 100,000 item embeddings of 128 float32 dimensions need, in MB (1 MB = 1,000,000 bytes)?', ['51.2', '51'], '100,000 × 128 × 4 bytes = 51.2 million bytes.'),
      mc('Why use approximate nearest-neighbour search?', ['It trades a little recall for much lower latency', 'It is perfectly exact', 'It needs no index', 'It trains the ranking model'], 'Exact search does not scale to the latency budget.'),
      match('Match the tool to the problem it solves', [['Cache', 'Skip recomputing repeated requests'], ['Approximate nearest neighbour', 'Fast candidate retrieval over millions of vectors'], ['Autoscaling', 'Add capacity as load grows'], ['Quantised embeddings', 'Smaller index and less memory']]),
      mc('Peak load is 600 requests per second and one replica handles 50 at the target latency. How many replicas do you need with about 30% headroom?', ['16', '12', '8', '30'], '600 ÷ 50 = 12; times 1.3 is 15.6, rounded up to 16.'),
      tf('Caching is useful only when requests repeat exactly.', false, 'You can also cache features, embeddings and partial results.')),

    L('Common mistakes and debugging',
      info('Design mistakes that cost points', 'Typical errors: naming a model before asking questions, no baseline, a metric that ignores the real cost, a random split on time-ordered data, forgetting **cold start**, and no plan for monitoring.\n\nThe same slips appear in real systems as bugs.'),
      mc('A candidate names a transformer before asking a single question. What is the mistake?', ['Skipping requirements and the baseline', 'Choosing a model', 'Speaking too clearly', 'Nothing is wrong'], 'Requirements and a baseline come first.'),
      mc('A recommender is evaluated with a random split of click logs. What is the problem?', ['Future behaviour leaks into training, so split by time', 'Splits must always be random', 'There is too little data', 'Nothing is wrong'], 'Imitate predicting the future from the past.'),
      info('Cache keys and stale data', 'Bugs in serving code often come from caches: a key that ignores part of the input, an entry that never expires, or a cached feature that is hours old when the model expects minutes.'),
      mc('What is the bug in this code?', ['The cache key ignores user_id, so everyone gets the first user’s results', 'Caches are too slow', 'rank is misspelt', 'Nothing is wrong'], 'Include every input that changes the answer in the key.', 'def top_items(user_id):\n    key = "recs"\n    if key in cache:\n        return cache[key]\n    cache[key] = rank(user_id)\n    return cache[key]'),
      fillc('key = f"recs:{___}"', ['user_id', '"recs"', '1', 'None'], 'The key must identify the user whose results are stored.'),
      match('Match the symptom to the design problem', [['Popular items keep winning', 'A feedback loop: add exploration'], ['New users get nothing useful', 'Cold start: fall back to popularity and content features'], ['Offline metric up, online flat', 'The offline proxy is not linked to the business metric'], ['Fine at night, slow at peak', 'Capacity was planned for the average, not the peak']]),
      mc('A fraud model is 99.9% accurate but misses most fraud, which is 0.1% of cases. What went wrong in the design?', ['Accuracy was the wrong metric for a rare class', 'There was too much data', 'The latency was too low', 'There was too much logging'], 'Use precision, recall and costs for imbalanced problems.'),
      order('Order the fix for a recommender that narrows to a few items', ['Confirm with diversity and coverage metrics', 'Check the logged data: shown items drive clicks', 'Add exploration and more varied candidate sources', 'Retrain with randomised slots or propensity weights', 'Monitor coverage and long-term engagement'], 'Measure the loop, break it, and keep watching.')),

    L('Case study: homepage recommendations',
      info('The situation', 'A streaming service has **50,000 titles**, **10 million daily users** and a page that must load in **300 ms**. The goal is long-term viewing, not just clicks.\n\nYou design the system step by step.'),
      mc('What do you ask first?', ['What success means (watch time, retention, variety) and what must not get worse', 'Which GPU to use', 'Which framework to use', 'What colour the page is'], 'Requirements and the metric come before the model.'),
      mc('Which baseline do you propose?', ['Popular titles per country and genre, plus recently watched', 'A deep neural network', 'Random titles', 'No recommendations'], 'Simple, fast to ship and hard to beat by a lot.'),
      info('Two stages', '**Retrieval** cuts 50,000 titles to about 500 with embeddings and co-watch signals. **Ranking** scores those 500 with a richer model and many features. A **re-ranking** step then applies rules: hide what was already watched, respect age ratings, add variety.\n\nEach stage is a trade-off between cost and accuracy.'),
      mc('Why not score all 50,000 titles with the heavy model on every request?', ['It is too slow and costly for the latency budget', 'Heavy models are inaccurate', 'It is illegal', 'The results cannot be logged'], 'Funnel with cheap methods first.'),
      type('Ranking 500 candidates at 0.1 ms each, one after another, takes how many milliseconds?', ['50'], '500 × 0.1 ms = 50 ms.'),
      mc('A new release has no watch history. What helps?', ['Content features and an exploration slot', 'Hide it from everyone', 'Wait a year for data', 'Remove the ranking stage'], 'Cold start needs content signals and deliberate exposure.'),
      order('Order the evaluation plan', ['Offline: recall@k and NDCG on a time-based split', 'Check slices: new users, regions and devices', 'A/B test on watch time with guardrails on latency and complaints', 'Run long enough to cover weekly cycles', 'Roll out and keep a holdout to track the long-term effect'], 'Offline to filter, online to decide, holdout to learn.'),
      mc('An A/B test shows watch time +2% but next-month retention −1%. Decision?', ['Do not ship yet: investigate, since short-term engagement may hurt long-term value', 'Ship immediately', 'Ignore retention', 'Stop the test after an hour'], 'Guardrail metrics exist to catch exactly this.')),

    L('Interview drill: ML system design',
      info('The rubric', 'Interviewers usually score four things: **structure** (do you follow a clear path), **trade-offs** (do you say what each choice costs), **depth** where they probe, and **communication** (do you think aloud and invite corrections).\n\nA complete but shallow tour scores lower than a structured answer that goes deep where asked.'),
      mc('"Design a spam filter for a messaging app." Best opening?', ['Ask about volume, latency, the cost of false positives versus misses, and available labels', 'Name a model', 'Describe GPUs', 'Say it is easy'], 'Questions shape the design.'),
      mc('Follow-up: "Which metric would you use?"', ['Recall at a fixed low rate of wrongly blocked legitimate messages, tied to user complaints', 'Accuracy only', 'Training loss only', 'The number of rules'], 'Spam is imbalanced and false positives are costly.'),
      info('Handling "what would you change?"', 'Do not defend your design stubbornly. Name the **bottleneck**, propose a **fix** and state its **cost**: "Feature lookups dominate latency; I would cache them, at the price of some staleness."\n\nThis is the shape of a senior answer.'),
      mc('"Traffic grows 10 times. What breaks first?"', ['Probably feature lookups or the ranking stage; estimate the load, then cache, shard or simplify the model', 'Nothing will break', 'The logo', 'The labels'], 'Estimate, locate the bottleneck, propose a fix.'),
      mc('"The model is less accurate for one group of users. What do you do?"', ['Measure per-group metrics, find data and label causes, mitigate, and monitor', 'Ignore it', 'Hide the group attribute and assume it is fair', 'Remove the model for ever'], 'Fairness is measured by slices, not assumed.'),
      match('Match the interview question to the core of the answer', [['"Why this model?"', 'Start from a baseline and justify extra complexity with evidence'], ['"How do you keep it fresh?"', 'Retraining triggers, streaming features and monitoring'], ['"What if labels are scarce?"', 'Weak labels, human review and active learning'], ['"Build or buy?"', 'Cost, speed, control and data sensitivity']]),
      order('Order a strong answer to "Design a system that detects fake reviews"', ['Clarify the goal, volume, cost of errors and labels', 'Define metrics and a baseline of simple rules', 'Features and model: text, account behaviour and graph signals', 'Architecture: a real-time check, batch review and a human queue', 'Evaluation, monitoring against adversaries, and risks'], 'The standard design-answer path, applied.'),
      tf('Pausing to flag a risk you have just noticed in your own design is a good habit.', true, 'It shows self-review, which interviewers value.'))
  ]
};
